cd /testbed; cat > /tmp/t.js <<'EOF'
const http=require('http');const axios=require('/testbed');
const s=http.createServer((q,r)=>{let n=0;q.on('data',c=>n+=c.length);q.on('end',()=>r.end(String(n)))}).listen(0,async()=>{
 const u='http://localhost:'+s.address().port;
 for (const c of [{},{maxBodyLength:-1},{maxBodyLength:10}]) {
  try{const r=await axios.post(u,'x'.repeat(2e7),c);console.log('ok',r.data)}catch(e){console.log('err',e.message)}}
 s.close();});
EOF
node /tmp/t.js

